#include <bits/stdc++.h>
using namespace std;
bool compare(pair<int,int> a,pair<int,int> b) { //排序比较函数
    return a.second < b.second;
}
int main() {
    int n, k;
    cin >> n;
    vector<pair<int,int>> a;  //学号和领奖顺序数组
    for(int i=0; i<n; i++) {
        cin >> k;
        a.push_back({i+1, k});
    }
    sort(a.begin(), a.end(), compare); //按领奖顺序排序
    for(int i=0; i<n; i++) {
        cout << a[i].first << " ";  //输出学号
    }
    return 0;
}
